function C:shootTweetAll(c)
  if not coroutine.isyieldable() then spawn(C.shootTweetAll, self, c) return end
  if PoketterManager._tweetQueue.Count ~= 0 and not PoketterManager.isShootRunning.Value and not self._stopLoading then
    PoketterManager.isShootRunning.Value = true
    self:ShowLoading(true)
    spawn(function() self:SpawnTweetAll() end)
  end
end

function C:SpawnTweetAll()
  if not coroutine.isyieldable() then spawn(C.SpawnTweetAll, self) return end
  while PoketterManager._tweetQueue.Count >= 1 do
    UniTask.WhenAny(UniTask.Delay(Constants.FAST, false, "Update", self:GetCancellationTokenOnDestroy(), false), UniTask.WaitUntil(function() return Input.GetMouseButtonDown(0) or PoketterView2D.Player:GetButtonDown("Click") end, "Update", self:GetCancellationTokenOnDestroy(), false))
    local tw = PoketterManager:AddHistoryFromQueue()
    if PoketterManager._tweetQueue.Count == 0 then
      self:ShowLoading(false)
    end
    self:shootTweetOne(tw)
  end
  PoketterManager.isShootRunning.Value = false
end

